const PUBLICAS = ['id', 'fecha_solicitud', 'empleado', 'departamento', 'tipo', 'desde', 'hasta', 'dias',
  'saldo_previo', 'estado', 'comentario', 'conflictos', 'decidido_en'];

// Devuelve las solicitudes de la plantilla de ejemplo (comunes a todos, de solo lectura) y debajo
// las del visitante, en el orden en que las envió y marcadas como suyas. Nunca expone el sid.
const q = $('Listar ausencias').first().json.query ?? {};
const sid = /^[a-f0-9]{32}$/.test(String(q.sid ?? '')) ? String(q.sid) : null;
const todas = $input.all().map((i) => i.json);
const publica = (r) => {
  const f = { tuya: r.sid !== 'demo' };
  for (const k of PUBLICAS) f[k] = r[k];
  return f;
};
const demo = todas.filter((r) => r.sid === 'demo')
  .sort((a, b) => String(a.fecha_solicitud).localeCompare(String(b.fecha_solicitud)));
const propias = sid === null ? [] : todas
  .filter((r) => r.sid === sid)
  .sort((a, b) => Number(a.creado_ms) - Number(b.creado_ms));
return [{ json: { filas: demo.concat(propias).map(publica) } }];

// Valida la solicitud del visitante con las reglas del flujo real de RRHH. Compara con su propia hoja
// y con la plantilla de ejemplo (sid 'demo'), para que se vean las coincidencias del equipo.
const b = $('Crear ausencia').first().json.body ?? {};
const todas = $input.all().map((i) => i.json).filter((r) => r.sid);
const fallo = (error, status = 400) => [{ json: { ok: false, status, error } }];

const sid = String(b.sid ?? '');
if (!/^[a-f0-9]{32}$/.test(sid)) return fallo('Identificador de sesión no válido');
const propias = todas.filter((r) => r.sid === sid);
const companeros = todas.filter((r) => r.sid === 'demo');
if (propias.length >= 20) return fallo('Has llegado al máximo de 20 solicitudes de prueba. Se borran solas a las 2 horas.', 429);
if (todas.length - companeros.length >= 400) return fallo('La demo está llena ahora mismo. Vuelve dentro de un rato.', 429);

const DIAS_ANUALES = 22;
const EMPLEADOS = {
  'Marta Soler': 'Producción',
  'Laura Gómez': 'Producción',
  'Nuria Ferrer': 'Administración',
  'Hugo Ortiz': 'Comercial',
  'Pablo Cano': 'Calidad',
};
const TIPOS = ['Vacaciones', 'Asuntos propios', 'Permiso retribuido'];
// Festivos nacionales fijos y Viernes Santo de 2026 y 2027.
const FESTIVOS = ['01-01', '01-06', '05-01', '08-15', '10-12', '11-01', '12-06', '12-08', '12-25'];
const VIERNES_SANTO = ['2026-04-03', '2027-03-26'];
const DIA_MS = 24 * 3600 * 1000;

const dia = (s) => {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s || ''));
  if (!m) return null;
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  return Number.isNaN(d.getTime()) ? null : d;
};
const iso = (d) => d.toISOString().slice(0, 10);
const laborable = (d) => {
  const s = iso(d);
  const w = d.getUTCDay();
  return w !== 0 && w !== 6 && !FESTIVOS.includes(s.slice(5)) && !VIERNES_SANTO.includes(s);
};
const contar = (desde, hasta) => {
  let n = 0;
  for (let d = new Date(desde); d <= hasta; d = new Date(d.getTime() + DIA_MS)) if (laborable(d)) n++;
  return n;
};

const hoy = dia($now.setZone('Europe/Madrid').toFormat('yyyy-MM-dd'));

const departamento = EMPLEADOS[b.empleado];
if (!departamento) return fallo('Empleado: elige uno de la lista');
if (!TIPOS.includes(b.tipo)) return fallo('Tipo de ausencia: elige uno de la lista');
const desde = dia(b.desde);
const hasta = dia(b.hasta);
if (!desde || !hasta) return fallo('Indica las dos fechas.');
if (hasta < desde) return fallo('La fecha final no puede ser anterior a la inicial.');
if ((hoy - desde) / DIA_MS > 7) return fallo('No se pueden pedir ausencias de hace más de una semana.');
if ((desde - hoy) / DIA_MS > 366) return fallo('No se pueden pedir ausencias con más de un año de antelación.');
if ((hasta - desde) / DIA_MS > 30) return fallo('Cada solicitud admite como máximo 31 días seguidos.');
const dias = contar(desde, hasta);
if (!dias) return fallo('Esas fechas son fin de semana o festivo: no suman días laborables.');

const vivas = propias.concat(companeros).filter((r) => r.estado !== 'Rechazada' && r.estado !== 'Caducada');
const solapa = (r) => String(r.desde) <= iso(hasta) && String(r.hasta) >= iso(desde);
const mias = vivas.filter((r) => r.empleado === b.empleado);
if (mias.some(solapa)) return fallo(`${b.empleado} ya tiene una solicitud pendiente o aprobada que coincide con esas fechas.`);
if (mias.filter((r) => r.estado === 'Pendiente').length >= 3) return fallo(`${b.empleado} ya tiene 3 solicitudes pendientes de respuesta.`);

const anio = String(desde.getUTCFullYear());
const reservados = mias
  .filter((r) => r.tipo === 'Vacaciones' && String(r.desde).startsWith(anio))
  .reduce((a, r) => a + Number(r.dias), 0);
const saldo = DIAS_ANUALES - reservados;
if (b.tipo === 'Vacaciones' && dias > saldo) return fallo(`Pides ${dias} días de vacaciones y a ${b.empleado} le quedan ${saldo} en ${anio}.`);

const conflictos = vivas
  .filter((r) => r.empleado !== b.empleado && r.departamento === departamento && solapa(r))
  .map((r) => `${r.empleado} (${r.desde} a ${r.hasta}, ${String(r.estado).toLowerCase()})`)
  .join('; ');

return [{ json: { ok: true, fila: {
  sid,
  fecha_solicitud: $now.setZone('Europe/Madrid').toFormat('yyyy-MM-dd HH:mm'),
  empleado: b.empleado, departamento, tipo: b.tipo,
  desde: iso(desde), hasta: iso(hasta), dias, saldo_previo: saldo,
  estado: 'Pendiente',
  comentario: String(b.comentario ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, 200),
  conflictos, decidido_en: '', creado_ms: Date.now(),
} } }];

const PUBLICAS = ['id', 'fecha_solicitud', 'empleado', 'departamento', 'tipo', 'desde', 'hasta', 'dias',
  'saldo_previo', 'estado', 'comentario', 'conflictos', 'decidido_en'];

// Devuelve la solicitud guardada y el correo que el flujo real mandaría a la responsable (mismo texto que "Preparar aviso").
// En la demo no sale ningún correo: los botones Aprobar y Rechazar están en la página.
const r = $('Guardar solicitud demo').first().json;
const solicitud = { tuya: true };
for (const k of PUBLICAS) solicitud[k] = r[k];

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const lineas = [
  `${r.empleado} (${r.departamento}) pide ${r.tipo.toLowerCase()}.`,
  '',
  `Fechas: del ${r.desde} al ${r.hasta} (${r.dias} ${r.dias === 1 ? 'día laborable' : 'días laborables'})`,
  `Vacaciones antes de esta solicitud: quedaban ${r.saldo_previo} de 22 días`,
];
if (r.comentario) lineas.push(`Comentario: ${r.comentario}`);
lineas.push('');
lineas.push(r.conflictos ? `⚠ Coincide con: ${r.conflictos}` : 'Sin coincidencias con su departamento.');

const asunto = `${r.conflictos ? '⚠ ' : ''}Solicitud de ${r.tipo.toLowerCase()} · ${r.empleado} · ${r.desde} a ${r.hasta}`;
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222">${lineas.map(esc).join('<br>')}</div>`;

return [{ json: { ok: true, solicitud, correo: { de: 'RRHH', para: 'Responsable de RRHH', asunto, html } } }];

// Comprueba que la solicitud existe, es del visitante y sigue pendiente, y calcula el estado nuevo.
const b = $('Decidir ausencia').first().json.body ?? {};
const fallo = (error, status = 400) => [{ json: { ok: false, status, error } }];

const sid = String(b.sid ?? '');
if (!/^[a-f0-9]{32}$/.test(sid)) return fallo('Identificador de sesión no válido');
const id = Number(b.id);
if (!Number.isInteger(id) || id < 1) return fallo('Solicitud no válida');
if (!['aprobar', 'rechazar'].includes(b.decision)) return fallo('Decisión no válida');

const r = $input.all().map((i) => i.json).find((x) => x.sid === sid && Number(x.id) === id);
if (!r) return fallo('No se encuentra esa solicitud. Las de prueba se borran a las 2 horas; las de la plantilla de ejemplo no se pueden cambiar.', 404);
if (r.estado !== 'Pendiente') return fallo(`Esa solicitud ya está ${String(r.estado).toLowerCase()}.`, 409);

const estado = b.decision === 'aprobar' ? 'Aprobada' : 'Rechazada';
const decidido_en = $now.setZone('Europe/Madrid').toFormat('yyyy-MM-dd HH:mm');
return [{ json: { ok: true, id, sid, estado, decidido_en, fila: { ...r, estado, decidido_en } } }];

const PUBLICAS = ['id', 'fecha_solicitud', 'empleado', 'departamento', 'tipo', 'desde', 'hasta', 'dias',
  'saldo_previo', 'estado', 'comentario', 'conflictos', 'decidido_en'];

// Devuelve la solicitud ya decidida y el correo que el flujo real mandaría al empleado (misma plantilla que "Decisión").
const r = $('Comprobar decisión').first().json.fila;
const solicitud = { tuya: true };
for (const k of PUBLICAS) solicitud[k] = r[k];

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const saldo = r.estado === 'Aprobada' && r.tipo === 'Vacaciones' ? r.saldo_previo - r.dias : r.saldo_previo;
const frase = {
  Aprobada: `Tu solicitud de ${r.tipo.toLowerCase()} ha sido <b>aprobada</b>.`,
  Rechazada: `Tu solicitud de ${r.tipo.toLowerCase()} ha sido <b>rechazada</b>. Habla con tu responsable si necesitas más información.`,
}[r.estado];
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#1d2430">
<p>Hola ${esc(r.empleado.split(' ')[0])},</p>
<p>${frase}</p>
<p>Del ${esc(r.desde)} al ${esc(r.hasta)} · ${esc(r.dias)} ${r.dias === 1 ? 'día laborable' : 'días laborables'}.<br>
Vacaciones que te quedan este año: <b>${esc(saldo)}</b> de 22.</p>
<p style="color:#5b6676">Mensaje automático de la demo de RRHH. Todos los datos son inventados.</p></div>`;
const asunto = `Tu solicitud de ${r.tipo.toLowerCase()} (${r.desde} a ${r.hasta}): ${r.estado.toLowerCase()}`;

return [{ json: { ok: true, solicitud, correo: { de: 'RRHH', para: r.empleado, asunto, html } } }];
